import { QuoteAssets, QuoteTemplate } from './quotationHtml';
import { resolveQuotationType } from './quotationType';
import { BRAND_LOGOS, QUOTE_IMAGES } from './quotationAssetData';

/**
 * The brand images are embedded in the app as base64 text (quotationAssetData.ts,
 * generated by scripts/embed-quotation-assets.js). Reading bundled image files at
 * runtime works in Expo Go but fails in exported Android builds, embedded text
 * works everywhere, instantly and offline.
 */
export const templateOf = (q: any): QuoteTemplate => resolveQuotationType(q);

export const loadQuoteAssets = async (t: QuoteTemplate): Promise<QuoteAssets> => ({ ...QUOTE_IMAGES[t] });

/** Logos for the dealer strip. Brands without a logo file are simply left out. */
export async function loadBrandLogos(keys: string[]): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const k of keys) if (BRAND_LOGOS[k]) out[k] = BRAND_LOGOS[k];
  return out;
}
